# E02/E03: payroll grants are separate from financial-report approval.
obj('PayrollAccess', {'company_id':ID,'view':BOOL,'manage':BOOL,'approve':BOOL})
obj('PayrollPermissions', {'membership_id':ID,'view':BOOL,'manage':BOOL,'approve':BOOL,'version':VERSION})
obj('PayrollPermissionsRequest', {'view':BOOL,'manage':BOOL,'approve':BOOL,'reason':TEXT})
endpoint('get',C+'/payroll-access','getPayrollAccess','PayrollAccess')
endpoint('get',C+'/memberships/{membership_id}/payroll-permissions','getPayrollPermissions','PayrollPermissions',permission='company.owner')
endpoint('put',C+'/memberships/{membership_id}/payroll-permissions','setPayrollPermissions','PayrollPermissions','PayrollPermissionsRequest',permission='company.owner',versioned=True)
obj('CompanyModuleValues', {key:BOOL for key in ('accounting','cash','balances','invoices','settlements','moadian','forecast','payroll')})
obj('CompanyModules', {'company_id':ID,'modules':ref('CompanyModuleValues'),'version':VERSION})
obj('CompanyModulesRequest', {'modules':ref('CompanyModuleValues'),'reason':TEXT})
endpoint('get',C+'/modules','getCompanyModules','CompanyModules')
endpoint('put',C+'/modules','setCompanyModules','CompanyModules','CompanyModulesRequest',permission='company.owner',versioned=True)
obj('ExtensionAccessEvent', {'id':ID,'created_at':TIME,'actor_name':TEXT,'recipient_name':nullable(TEXT),'kind':enum('payroll_permissions','company_modules'),'reason':TEXT,'before_value':{'type':'object','additionalProperties':True},'after_value':{'type':'object','additionalProperties':True}})
endpoint('get',C+'/extension-access-events','listExtensionAccessEvents',permission='company.owner',list_item='ExtensionAccessEvent')
